const M2W = (() => {
  const store = { get() { try { return localStorage.getItem("m2w.lang"); } catch (e) { return null; } }, set(v) { try { localStorage.setItem("m2w.lang", v); } catch (e) {} } };
  const ok = v => v === "zh" || v === "en" ? v : null;
  const dflt = ok(document.documentElement.dataset.defaultLang) || "zh";
  const m = { lang: ok(store.get()) || dflt, miss: new Set(), subs: [] };
  document.documentElement.lang = m.lang;
  m.onLang = fn => m.subs.push(fn);
  /* switch the language; `persist` writes localStorage (the tab that was clicked), the others only follow */
  m.set = (l, persist = true) => {
    if (!ok(l) || l === m.lang) return;
    m.lang = l; document.documentElement.lang = l; if (persist) store.set(l);
    m.apply(); m.subs.forEach(fn => fn(l));
  };
  /* static markup: data-i (text), data-i-ph (placeholder), data-i-title (title), data-i-aria (aria-label); the Chinese in the element is the key */
  m.apply = (root = document) => {
    for (const [a, attr] of [["i", null], ["i-ph", "placeholder"], ["i-title", "title"], ["i-aria", "aria-label"]]) {
      root.querySelectorAll(`[data-${a}]`).forEach(el => {
        if (el.getAttribute(`data-zh-${a}`) == null) el.setAttribute(`data-zh-${a}`, attr ? el.getAttribute(attr) : el.textContent);
        const v = t(el.getAttribute(`data-zh-${a}`)); if (attr) el.setAttribute(attr, v); else el.textContent = v;
      });
    }
  };
  return m;
})();
