/* the workspace pages per project kind (sidebar and tab bar); a kind not listed here uses the memory pages */
const KIND_TABS = { feature: [["gather", "upload", "素材"], ["spec", "check", "需求"], ["plan", "plan", "方案"], ["play", "play", "试玩"], ["status", "status", "开发状态"], ["keep", "home", "带回家"]],
  gameplay: [["gather", "upload", "素材"], ["mechanics", "map", "机制映射"], ["content", "cards", "内容"], ["balance", "chart", "平衡"], ["plan", "plan", "方案"], ["play", "play", "试玩"], ["status", "status", "开发状态"]] };
const KIND_ALIAS = { feature: { home: "spec", board: "spec", people: "spec" }, gameplay: { home: "mechanics", board: "mechanics", people: "content" } };
const tabOf = (kind, k) => ({ board: "home", now: "status", prefs: "status", ...(KIND_ALIAS[kind] || {}) })[k] || k;
/* texts the server sends together with their English ({中文: English}, e.g. a game package's description): added to EN, never overriding */
function addTexts(m) { for (const [zh, en] of Object.entries(m || {})) if (en && !(zh in EN)) EN[zh] = en; }
function t(zh, vars) {
  const kw = (KIND_WORDS[M2W.kind] || {})[zh]; if (kw != null) zh = kw;
  let s = zh;
  if (M2W.lang === "en") {
    s = EN[zh];
    if (s == null) { s = zh; if (/[一-鿿]/.test(zh)) M2W.miss.add(zh); }
  }
  if (Array.isArray(s)) s = vars && vars.n === 1 ? s[0] : s[1];
  return vars ? s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? "") : s;
}
/* times: stored `at` values are naive UTC ("2026-10-16T05:12:00", a bare date means that day at 00:00 UTC); shown in the browser's time zone */
const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const toDate = at => { if (!at) return null; const s = String(at); const d = new Date(/[zZ]|[+-]\d\d:?\d\d$/.test(s) ? s : s.length <= 10 ? s + "T00:00:00Z" : s + "Z"); return isNaN(d) ? null : d; };
const pad2 = n => String(n).padStart(2, "0");
const dayOf = d => M2W.lang === "en" ? `${MON[d.getMonth()]} ${d.getDate()}` : `${d.getMonth() + 1} 月 ${d.getDate()} 日`;
const fmtHM = at => { const d = toDate(at); return d ? `${pad2(d.getHours())}:${pad2(d.getMinutes())}` : ""; };
const fmtDay = at => { const d = toDate(at); return d ? dayOf(d) : ""; };
const dayKey = at => { const d = toDate(at); return d ? `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}` : ""; };
const fmtAt = at => { const d = toDate(at); return d ? `${dayOf(d)}${M2W.lang === "en" ? "," : ""} ${pad2(d.getHours())}:${pad2(d.getMinutes())}` : String(at || ""); };
/* a calendar date with no time of day (the wedding date): no time-zone shift */
const fmtDate = s => { const m = /^(\d{4})-(\d\d)-(\d\d)/.exec(s || ""); return !m ? (s || "") : M2W.lang === "en" ? `${MON[+m[2] - 1]} ${+m[3]}, ${m[1]}` : `${m[1]} 年 ${+m[2]} 月 ${+m[3]} 日`; };
const fmtShortDate = s => { const m = /^\d{4}-(\d\d)-(\d\d)/.exec(s || ""); return !m ? (s || "") : M2W.lang === "en" ? `${MON[+m[1] - 1]} ${+m[2]}` : `${+m[1]} 月 ${+m[2]} 日`; };

/* the 中 | EN switch (shell: workspace tab bar; standalone app: top bar) */
function langSwitchHtml() {
  return `<span class="lang" role="group" aria-label="Language"><button data-lang="zh" class="${M2W.lang === "zh" ? "on" : ""}">中</button><button data-lang="en" class="${M2W.lang === "en" ? "on" : ""}">EN</button></span>`;
}
function wireLangSwitch(root = document) {
  root.querySelectorAll(".lang button").forEach(b => b.onclick = () => M2W.set(b.dataset.lang));
}
function syncLangSwitch() { document.querySelectorAll(".lang button").forEach(b => b.classList.toggle("on", b.dataset.lang === M2W.lang)); }
M2W.onLang(syncLangSwitch);
/* another tab of the same browser (or the shell, for the embedded workspace) changed the choice */
window.addEventListener("storage", e => { if (e.key === "m2w.lang" && (e.newValue === "zh" || e.newValue === "en")) M2W.set(e.newValue, false); });
